//! Original analytic fixtures; never generated by a proprietary CAD application.
use crate::*;
use solidcraft_geom::Vec3;
mod channel;
mod extended;
mod exterior;
mod through;

pub const CASES: &[&str] =
    &["face", "contour", "pocket", "drill", "concave-islands", "multi-operation", "clamped-through-holes", "external-contour", "narrow-channel"];

/// Independent point expectations, indexed by the completed operation count.
pub fn probes(name: &str, completed: usize) -> Result<Vec<([f64; 2], f64)>> {
    match name {
        "face" | "pocket" | "drill" => Ok(vec![([10., 10.], 5.)]),
        "contour" => Ok(vec![([10., 10.], 6.)]),
        "narrow-channel" if completed == 1 => Ok(vec![([10., 10.], 5.), ([4., 10.], 5.), ([16., 10.], 5.), ([10., 11.2], 6.), ([3.8, 10.], 6.)]),
        "concave-islands" => Ok(vec![([6., 6.], 6.), ([6., 13.], 6.), ([14., 14.], 6.), ([15., 6.], 4.), ([6., 9.], 4.)]),
        "clamped-through-holes" if (1..=2).contains(&completed) => {
            Ok(vec![([6., 10.], 0.), ([14., 10.], if completed == 2 { 0. } else { 6. }), ([10., 10.], 6.), ([6.6, 10.], 6.)])
        }
        "external-contour" if (1..=2).contains(&completed) => {
            Ok(vec![([10., 10.], 6.), ([5.1, 10.], 6.), ([4.5, 10.], if completed == 1 { 4.2 } else { 4. }), ([1., 1.], 6.)])
        }
        "multi-operation" if (1..=4).contains(&completed) => {
            let floor = [5.5, 4.2, 4., 4.].get(completed - 1).copied().ok_or_else(|| Error("unknown stage".into()))?;
            Ok(vec![([1., 1.], 5.5), ([6., 6.], 5.5), ([14., 14.], 5.5), ([6., 9.], floor), ([15., 6.], if completed == 4 { 3. } else { floor })])
        }
        _ => invalid("unknown analytic stage"),
    }
}

pub fn fixture(strategy: &str) -> Result<JobInput> {
    if strategy == "narrow-channel" {
        return channel::fixture();
    }
    if strategy == "external-contour" {
        return exterior::fixture();
    }
    if strategy == "clamped-through-holes" {
        return through::fixture();
    }
    if matches!(strategy, "concave-islands" | "multi-operation") {
        return extended::fixture(strategy);
    }
    let tool = Tool {
        id: 1,
        name: "6 mm center-cutting end mill".into(),
        number: 1,
        kind: ToolKind::FlatEndMill,
        diameter: 6.0,
        cutting_length: 20.0,
        shank_diameter: 6.0,
        overall_length: 50.0,
        holder_diameter: 20.0,
        holder_length: 30.0,
        tip_angle: 118_f64.to_radians(),
    };
    let setup = Setup {
        id: 1,
        name: "Analytic plate".into(),
        stock: Stock { min: Vec3::ZERO, max: Vec3::new(20.0, 20.0, 6.0) },
        frame: Frame::default(),
        models: vec![BodyRef { body: "Plate".into(), occurrence: vec![] }],
        fixtures: vec![],
        clearance: 15.0,
        retract: 10.0,
        work_offset: 54,
    };
    let boundary = Boundary {
        outer: (0..128)
            .map(|i| {
                let a = i as f64 * std::f64::consts::TAU / 128.;
                [10. + 8. * a.cos(), 10. + 8. * a.sin()]
            })
            .collect(),
        islands: vec![],
    };
    let geometry = match strategy {
        "face" => Strategy::Face,
        "contour" => Strategy::Contour { boundary, inside: true },
        "pocket" => Strategy::Pocket { boundary },
        "drill" => Strategy::Drill { holes: vec![[10.0, 10.0]], peck: Some(1.0), full_diameter: false },
        _ => return invalid("unknown analytic fixture"),
    };
    let mut tool = tool;
    if strategy == "drill" {
        tool.kind = ToolKind::TwistDrill;
        tool.diameter = 1.0;
        tool.shank_diameter = 1.0;
        tool.name = "1 mm twist drill".into();
    }
    let operation = Operation {
        id: 1,
        name: strategy.into(),
        setup: 1,
        tool: 1,
        geometry,
        source: None,
        hole_sources: vec![],
        top: 6.0,
        bottom: 5.0,
        stepdown: 1.0,
        stepover: if strategy == "drill" { 0.5 } else { 2.0 },
        feed: 300.0,
        plunge_feed: 100.0,
        spindle: 6000.0,
        allowance: 0.0,
        climb: true,
        tolerance: TOLERANCE,
        coolant: false,
        ramp_angle: None,
        lead_distance: 0.0,
    };
    let a = Vec3::new(0.0, 0.0, 5.0);
    let b = Vec3::new(20.0, 0.0, 5.0);
    let c = Vec3::new(20.0, 20.0, 5.0);
    let d = Vec3::new(0.0, 20.0, 5.0);
    let mut input = JobInput {
        setup,
        tools: vec![tool],
        operations: vec![operation],
        geometry: Geometry { target: vec![[a, b, c], [a, c, d]], fixtures: vec![], fixture_groups: vec![] },
        fingerprint: String::new(),
    };
    if strategy == "drill" {
        input.geometry.target = drilled_plate_target();
    }
    if matches!(strategy, "contour" | "pocket") {
        input.geometry.target = round_pocket_target();
    }
    input.fingerprint = crate::fingerprint(&input)?;
    Ok(input)
}

// Original circular pocket with the same faceted boundary as its input recipe.
// Chord error at radius 8 with 128 segments is 0.002410 mm; the recipe itself is
// this polygon, not an unrecorded exact circle.
fn round_pocket_target() -> Vec<[Vec3; 3]> {
    let mut triangles = Vec::new();
    let ring = |i: usize| {
        let a = (i % 128) as f64 * std::f64::consts::TAU / 128.;
        let (y, x) = a.sin_cos();
        let outer = if x.abs() >= y.abs() {
            [10. + 10. * x.signum(), 10. + 10. * y / x.abs(), 6.]
        } else {
            [10. + 10. * x / y.abs(), 10. + 10. * y.signum(), 6.]
        };
        ([10. + 8. * x, 10. + 8. * y, 6.], outer)
    };
    for i in 0..128 {
        let (a, c) = ring(i);
        let (b, d) = ring(i + 1);
        triangles.extend([[a.into(), c.into(), d.into()], [a.into(), d.into(), b.into()]]);
        let e = [a[0], a[1], 5.];
        let f = [b[0], b[1], 5.];
        triangles.extend([[[10., 10., 5.].into(), e.into(), f.into()], [a.into(), b.into(), f.into()], [a.into(), f.into(), e.into()]]);
    }
    triangles
}

// Original faceted plate with a blind drilled hole, vertical wall and cone.
fn drilled_plate_target() -> Vec<[Vec3; 3]> {
    let mut triangles = Vec::new();
    let n = 48;
    let slope = 1.0 / (59_f64.to_radians().tan());
    for k in 0..n {
        let point = |index: usize, r: f64, z: f64| {
            let a = index as f64 * std::f64::consts::TAU / n as f64;
            [10. + r * a.cos(), 10. + r * a.sin(), z]
        };
        let outer = |index: usize| {
            let a = index as f64 * std::f64::consts::TAU / n as f64;
            point(index, 10. / a.cos().abs().max(a.sin().abs()), 6.)
        };
        let a = point(k, 0.5, 6.);
        let b = point(k + 1, 0.5, 6.);
        let c = outer(k);
        let d = outer(k + 1);
        triangles.push([a.into(), c.into(), d.into()]);
        triangles.push([a.into(), d.into(), b.into()]);
        let e = point(k, 0.5, 5. + 0.5 * slope);
        let f = point(k + 1, 0.5, 5. + 0.5 * slope);
        triangles.push([[10., 10., 5.].into(), e.into(), f.into()]);
        triangles.push([a.into(), b.into(), f.into()]);
        triangles.push([a.into(), f.into(), e.into()]);
    }
    triangles
}

#[cfg(test)]
#[allow(clippy::unwrap_used)]
mod tests {
    use super::*;
    #[test]
    fn all_strategies_round_trip() {
        for name in ["face", "contour", "pocket", "drill"] {
            let input = fixture(name).unwrap();
            let path = generate::generate(input.clone()).unwrap();
            let parsed = nc::round_trip(&path, &input.setup, &input.tools).unwrap();
            assert!(!nc::segments(&parsed, &input.setup).unwrap().is_empty());
        }
    }
    #[test]
    fn missing_modes_and_unknown_words_fail() {
        let input = fixture("face").unwrap();
        for code in [
            "G0 X0 Y0 Z10\nM30",
            "G21 G90 G17 G94 G54\nG0 X0 Y0 Z15\nG43 H1\nM30",
            "G21 G90 G17 G94 G54\nG0 X0 Y0 Z15\nG0 XNaN\nM30",
            "G21 G90 G91\nM30",
        ] {
            assert!(nc::parse(code, &input.tools).is_err(), "{code}");
        }
    }
    #[test]
    fn cancelled_job_cannot_publish() {
        let mut g = generate::Generator::new(fixture("face").unwrap()).unwrap();
        g.cancel();
        assert!(g.step().is_err());
        assert!(g.finish().is_err());
    }
    #[test]
    fn malformed_geometry_rejected() {
        let mut i = fixture("pocket").unwrap();
        if let Strategy::Pocket { boundary } = &mut i.operations[0].geometry {
            boundary.outer = vec![[0.0, 0.0], [10.0, 10.0], [0.0, 10.0], [10.0, 0.0]];
        }
        assert!(generate::generate(i).is_err());
    }
    #[test]
    fn zero_budget_cannot_pass() {
        let i = fixture("face").unwrap();
        let p = generate::generate(i.clone()).unwrap();
        let nc = nc::round_trip(&p, &i.setup, &i.tools).unwrap();
        let r = verify::simulate(&i, &nc, verify::Limits { work: 1, ..Default::default() }).unwrap();
        assert_ne!(r.status, verify::Status::Pass);
    }
    #[test]
    fn equivalent_units() {
        let i = fixture("face").unwrap();
        let a = nc::parse("G21 G90 G17 G94 G54\nG0 X25.4 Y0 Z25.4\nM30", &i.tools).unwrap();
        let b = nc::parse("G20 G90 G17 G94 G54\nG0 X1 Y0 Z1\nM30", &i.tools).unwrap();
        assert_eq!(a.records[0].motion, b.records[0].motion);
    }
    #[test]
    fn direction_changes_arc_sweep() {
        let i = fixture("face").unwrap();
        let src = "G21 G90 G17 G94 G54\nG0 X1 Y0 Z15\nT1 M6\nS1000 M3\nG3 X0 Y1 I-1 J0 F100\nM5\nM30";
        let a = nc::segments(&nc::parse(src, &i.tools).unwrap(), &i.setup).unwrap();
        let b = nc::segments(&nc::parse(&src.replace("G3 ", "G2 "), &i.tools).unwrap(), &i.setup).unwrap();
        let len = |s: Vec<nc::Segment>| s.iter().map(|x| x.from.dist(x.to)).sum::<f64>();
        assert!((len(b) / len(a) - 3.0).abs() < 0.01);
    }
    #[test]
    fn speed_selection_does_not_start_a_stopped_spindle() {
        let i = fixture("face").unwrap();
        let src = "G21 G90 G17 G94 G54\nG0 X0 Y0 Z15\nT1 M6\nS6000\nG1 X2 F100\nM30";
        assert!(nc::segments(&nc::parse(src, &i.tools).unwrap(), &i.setup).is_err());
        let running = src.replace("S6000", "S6000 M3");
        let parsed = nc::parse(&running, &i.tools).unwrap();
        assert_eq!(parsed.records.last().unwrap().motion, Motion::Spindle { rpm: 0.0 });
    }
    #[test]
    fn unsafe_rapid_and_wide_shank_do_not_pass() {
        let mut i = fixture("face").unwrap();
        let rapid = "G21 G90 G17 G94 G54\nG0 X0 Y0 Z15\nT1 M6\nG0 X10 Y10 Z2\nM30";
        let p = nc::parse(rapid, &i.tools).unwrap();
        assert_ne!(
            verify::simulate(&i, &p, verify::Limits { cells: 2000, work: 100000, ..Default::default() }).unwrap().status,
            verify::Status::Pass
        );
        i.tools[0].diameter = 1.0;
        i.tools[0].cutting_length = 1.0;
        i.operations[0].stepover = 0.5;
        let shank = "G21 G90 G17 G94 G54\nG0 X-1 Y10 Z15\nT1 M6\nS6000 M3\nG1 Z3 F100\nM5\nM30";
        let p = nc::parse(shank, &i.tools).unwrap();
        let r = verify::simulate(&i, &p, verify::Limits { cells: 2000, work: 100000, ..Default::default() }).unwrap();
        assert_ne!(r.status, verify::Status::Pass);
        assert!(r.findings.iter().any(|f| f.kind.contains("shank") || f.kind.contains("holder") || f.kind == "budget_exhausted"));
    }
    #[test]
    fn gouge_and_fixture_overlap_are_blocked() {
        let mut i = fixture("face").unwrap();
        let path = generate::generate(i.clone()).unwrap();
        let code = nc::post(&path, &i.setup).unwrap().replace("Z5.000000", "Z4.000000");
        let p = nc::parse(&code, &i.tools).unwrap();
        let r = verify::simulate(&i, &p, Default::default()).unwrap();
        assert_eq!(r.status, verify::Status::Fail);
        i.geometry.fixtures.push([Vec3::new(9.0, 9.0, 6.0), Vec3::new(11.0, 9.0, 6.0), Vec3::new(10.0, 11.0, 10.0)]);
        let p = nc::round_trip(&path, &i.setup, &i.tools).unwrap();
        let r = verify::simulate(&i, &p, Default::default()).unwrap();
        assert_ne!(r.status, verify::Status::Pass);
    }
    #[test]
    fn simulation_observes_cancellation() {
        let i = fixture("face").unwrap();
        let p = generate::generate(i.clone()).unwrap();
        let nc = nc::round_trip(&p, &i.setup, &i.tools).unwrap();
        assert!(verify::simulate_cancellable(&i, &nc, Default::default(), || true).is_err());
    }
    #[test]
    fn islands_winding_ramps_and_tool_fit() {
        let mut i = fixture("pocket").unwrap();
        if let Strategy::Pocket { boundary } = &mut i.operations[0].geometry {
            boundary.outer.reverse();
            boundary.islands.push(vec![[9.0, 9.0], [11.0, 9.0], [11.0, 11.0], [9.0, 11.0]]);
        }
        i.tools[0].diameter = 2.0;
        i.operations[0].stepover = 0.5;
        i.operations[0].ramp_angle = Some(5_f64.to_radians());
        let path = generate::generate(i.clone()).unwrap();
        nc::round_trip(&path, &i.setup, &i.tools).unwrap();
        i.tools[0].diameter = 30.0;
        assert!(generate::generate(i).is_err());
    }
    #[test]
    fn hand_calculated_stock_and_drill_cone() {
        let i = fixture("face").unwrap();
        let path = generate::generate(i.clone()).unwrap();
        let nc = nc::round_trip(&path, &i.setup, &i.tools).unwrap();
        let report = verify::simulate(&i, &nc, Default::default()).unwrap();
        assert_eq!(report.status, verify::Status::Pass);
        assert!((report.remaining_volume_low - 2000.0).abs() < 1e-6);
        assert!((report.remaining_volume_high - 2000.0).abs() < 1e-6);
        let i = fixture("drill").unwrap();
        // Authored NC, independent of the generator. A 118-degree cone rises
        // r / tan(59 degrees) from its tip at every radial position r.
        let source = "G21 G90 G17 G94 G54\nG0 X10 Y10 Z15\nT1 M6\nS6000 M3\nG1 Z5 F100\nG0 Z15\nM5\nM30";
        let nc = nc::parse(source, &i.tools).unwrap();
        let actual = verify::probe_height(&i, &nc, [10.25, 10.0]).unwrap();
        assert!((actual - (5.0 + 0.25 / 59_f64.to_radians().tan())).abs() < 1e-9);
        assert_eq!(verify::probe_height(&i, &nc, [11.0, 10.0]).unwrap(), 6.0);
    }

    #[test]
    fn climb_pocket_follows_counterclockwise_outer_wall() {
        let i = fixture("pocket").unwrap();
        let path = generate::generate(i).unwrap();
        let points: Vec<_> = path
            .blocks
            .iter()
            .filter_map(|b| match b.motion {
                Motion::Linear { to, feed: 300.0 } => Some(to),
                _ => None,
            })
            .collect();
        // With M3, the pocket wall lies to the right of a counterclockwise cut.
        let last = &points[points.len() - 128..];
        let area: f64 = last.iter().zip(last.iter().cycle().skip(1)).take(128).map(|(a, b)| a.x * b.y - a.y * b.x).sum();
        assert!(area > 0.0);
    }
    #[test]
    fn cooperative_verification_yields_and_cancels() {
        use std::future::Future;
        use std::task::{Context, Poll, Waker};
        let input = fixture("face").unwrap();
        let path = generate::generate(input.clone()).unwrap();
        let nc = nc::round_trip(&path, &input.setup, &input.tools).unwrap();
        let cancel = std::cell::Cell::new(false);
        let yield_once = || {
            let mut first = true;
            std::future::poll_fn(move |_| {
                if first {
                    first = false;
                    Poll::Pending
                } else {
                    Poll::Ready(())
                }
            })
        };
        let mut future = std::pin::pin!(verify::simulate_cooperative(&input, &nc, Default::default(), || cancel.get(), yield_once));
        let mut cx = Context::from_waker(Waker::noop());
        assert!(future.as_mut().poll(&mut cx).is_pending());
        cancel.set(true);
        assert!(matches!(future.as_mut().poll(&mut cx), Poll::Ready(Err(_))));
    }
    #[test]
    fn excess_facing_stock_is_a_dimensional_failure() {
        let i = fixture("face").unwrap();
        let path = generate::generate(i.clone()).unwrap();
        let code = nc::post(&path, &i.setup).unwrap().replace("Z5.000000", "Z5.100000");
        let nc = nc::parse(&code, &i.tools).unwrap();
        let report = verify::simulate(&i, &nc, Default::default()).unwrap();
        assert_eq!(report.status, verify::Status::Pass); // no gouge or collision
        assert_eq!(report.finished_dimensions, verify::Status::Fail);
    }
}
